import json,re
from pathlib import Path
D=json.loads(Path('04_pipeline/work/pdfs/extracted.json').read_text())
sources={d['file'].split('_')[0]:d for d in D}
S='Savoy';B='Bagnoud';K='Kanton Wallis';F='Flaminio and Reynard';L='Louvin and Calvo'
rows=[]
headers=['编号','案例或主题','记录性质','事件或谈判时间','履行或到期时间','参与方及角色','权利或请求权性质','交换方向与内容','各方让步及谈判筹码','金额或水量','结果或状态（截至材料记载）','证据与不确定性','来源文件','PDF页码（从1起）','文内页码或条款','原文摘录（节选；断行合并）']
def add(title,kind,time,due,actors,rights,exchange,leverage,quantity,status,note,src,pages,start,length=650):
 d=sources[src]; ns=[int(x) for x in pages.split(',')]; t=' '.join(re.sub(r'\s+',' ',d['pages'][n-1]).strip() for n in ns)
 pos=t.find(start)
 assert pos>=0,(title,start)
 q=t[pos:pos+length]
 if pos+length<len(t):
  j=max(q.rfind('. '),q.rfind('; '))
  if j>len(q)*.5:q=q[:j+1]
  q+=' […]'
 loc='；'.join(str(n-1) for n in ns) if src==S else '见PDF页码'
 rows.append([f'R{len(rows)+1:03}',title,kind,time,due,actors,rights,exchange,leverage,quantity,status,note,d['file'],pages,loc,q])

